/**
 * SYNTHETIC ProjectionLab export (format 4.6.0). Every number, name and id here is invented.
 * It mirrors the *structure* of a real export (same key paths, same enum values) plus a few
 * variants (age references, a defined-benefit pension, a planned asset) so the committed tests
 * can exercise every mapping without touching private data.
 */

type Json = Record<string, unknown>;

const kw = (value: string, modifier?: string): Json => ({
  type: 'keyword',
  value,
  ...(modifier ? { modifier } : {}),
});
const dt = (value: string, modifier?: string): Json => ({
  type: 'date',
  value,
  ...(modifier ? { modifier } : {}),
});
const ms = (value: string, modifier?: string): Json => ({
  type: 'milestone',
  value,
  ...(modifier ? { modifier } : {}),
});

