/** Plan events carry their own ids; other plan events reference the EVENT id, not the entity id. */
const pe = (planIndex: number, entityId: string): string => `ee${planIndex}-${entityId.slice(3)}`;

const dividendCustom = (): Json => ({
  type: '%',
  data: [
    { x: 0.5, y: 1.5 },
    { x: 20, y: 2 },
    { x: 40, y: 2.5 },
  ],
});

function todayAccount(id: string, name: string, type: string, extra: Json = {}): Json {
  return {
    id,
    name,
    title: name,
    ...(type === 'savings' ? {} : { subtitle: 'synthetic account' }),
    icon: 'mdi-bank',
    color: 'blue',
    type,
    owner: 'me',
    balance: 10000,
    liquid: true,
    withdraw: true,
    investmentGrowthType: 'plan',
    investmentGrowthRate: 0,
    dividendType: 'plan',
    dividendRate: 0,
    withdrawAge: kw('now', 'include'),
    ...extra,
  };
}

function planAccountEvent(a: Json, index: number, planIndex: number): Json {
  const e: Json = {
    ...a,
    id: pe(planIndex, a.id as string),
    accountId: a.id,
    persistent: true,
    key: 0.1 + index / 100,
    planPath: 'accounts',
    monteCarloTreatment: 'auto',
    dividendRateCustom: dividendCustom(),
  };
  return e;
}

