function strategyBlock(over: Json = {}): Json {
  const bounds = (extra: Json = {}): Json => ({
    min: 0,
    minType: 'today$',
    minEnabled: false,
    max: 1000000,
    maxType: 'today$',
    maxEnabled: false,
    ...extra,
  });
  return {
    enabled: false,
    strategy: 'initial-%',
    start: ms('fi', 'include'),
    income: 'increase-spending',
    spendMode: 'withdraw',
    'initial-%': { amount: 4, ...bounds() },
    'fixed-%': { amount: 3.5, ...bounds({ min: 10000, minEnabled: true }) },
    'fixed-amount': { amount: 40000, amountType: 'today$', adjust: true },
    '1/N': bounds(),
    vpw: bounds(),
    'kitces-ratchet': {
      amount: 4,
      threshold: 50,
      ratchet: 10,
      cooldown: 3,
      ...bounds({ max: 10, maxType: '%', maxEnabled: true }),
    },
    'clyatt-95%': { amount: 4, percentOfPrevious: 95, ...bounds({ min: 10000, minEnabled: true }) },
    'guyton-klinger': { amount: 4.5, guardrail: 20, adjustment: 5, ...bounds() },
    ...over,
  };
}

