function buildProgress(): Json {
  // As in the source, `assets` is physical assets only and
  // netWorth = savings + taxable + taxDeferred + taxFree + crypto + assets - debt - loans.
  const point = (date: number, i: number): Json => {
    const p = {
      assets: 520000 + i * 6500,
      debt: 8000 - i * 200,
      loans: 330000 - i * 1000,
      savings: 25000 + i * 500,
      taxable: 50000 + i * 1500,
      taxDeferred: 60000 + i * 800,
      taxFree: 15000 + i * 600,
      crypto: 4000 + i * 100,
    };
    const netWorth =
      p.savings + p.taxable + p.taxDeferred + p.taxFree + p.crypto + p.assets - p.debt - p.loans;
    return { date, netWorth, ...p };
  };
  // 20:00 UTC = local midnight at UTC+4 the next day; the importer rounds to the nearest day.
  const base = Date.UTC(2026, 0, 31, 20, 0, 0);
  return {
    data: Array.from({ length: 9 }, (_, i) => point(base + i * 30 * 86_400_000, i)),
    lastUpdated: Date.UTC(2026, 10, 14, 20, 0, 0),
  };
}

export function buildSyntheticExport(): Json {
  const today = buildToday();
  return {
    meta: { version: '4.6.0', lastUpdated: Date.UTC(2026, 10, 14, 21, 0, 0) },
    today,
    plans: [0, 1, 2].map((i) => buildPlan(i, today)),
    settings: buildSettings(),
    progress: buildProgress(),
  };
}
